    assert_user_owned_directory('Whisper transcription directory', $transcribed, 0700);
    return {
        audio       => $audio,
        transcribed => $transcribed,
    };
}

sub resolved_sleek_paths {
    my ($home) = @_;
    my $task_dir = File::Spec->catdir($home, 'Syncthing', 'sleek');
    assert_user_owned_directory('Sleek task directory', $task_dir, 0700);
    my $task_file = safe_child_path($task_dir, 'whisper.txt');
    if (-e $task_file) {
        !-l $task_file && -f $task_file
            or fatal("Sleek task file is not regular: $task_file");
        my @stat = lstat_or_fatal('Sleek task file', $task_file);
        $stat[4] == $< or fatal("Sleek task file must be owned by the active user");
    } else {
        atomic_write_bytes($task_dir, 'whisper.txt', q{}, 0600);
    }
    chmod 0600, $task_file
        or fatal("cannot set Sleek task file mode: $!");
    return {
        directory => $task_dir,
        task_file => $task_file,
    };
}

sub config_file_path {
    my $path = $ENV{WHISPER_CONFIG_FILE} // $DEFAULT_CONFIG;
    assert_safe_absolute_path('Whisper configuration', $path);
    -f $path && !-l $path
        or fatal("Whisper configuration is unavailable: $path");
    my @stat = lstat_or_fatal('Whisper configuration', $path);
    ($stat[2] & 0022) == 0
        or fatal('Whisper configuration must not be writable by other users');
    if ($path eq $DEFAULT_CONFIG) {
        $stat[4] == 0
            or fatal('default Whisper configuration must be owned by root');
    } else {
        $stat[4] == $<
            or fatal('override Whisper configuration must be owned by the active user');
    }
    return $path;
}

sub whisper_config {
    my $path = config_file_path();
    my $raw = read_raw_limited($path, 16 * 1024);
    my %config;
    for my $line (split /\n/, $raw) {
        next if $line eq q{} || $line =~ /\A#/;
        $line =~ /\A([A-Z_]+)=([^\r\n]*)\z/
            or fatal("Whisper configuration contains an invalid line");
        my ($key, $value) = ($1, $2);
        exists $config{$key}
            and fatal("Whisper configuration contains duplicate $key");
        $config{$key} = $value;
    }
    for my $key (
        qw(
            WHISPER_CLI
            WHISPER_SERVER
            WHISPER_MODEL
            WHISPER_RUNTIME_THREADS
            WHISPER_PERSISTENT_MEM
        )
    ) {
        exists $config{$key} && length $config{$key}
            or fatal("Whisper configuration is missing $key");
    }
    assert_safe_absolute_path('WHISPER_CLI', $config{WHISPER_CLI});
    assert_safe_absolute_path('WHISPER_SERVER', $config{WHISPER_SERVER});
    assert_safe_absolute_path('WHISPER_MODEL', $config{WHISPER_MODEL});
    -x $config{WHISPER_CLI} && -f $config{WHISPER_CLI}
        or fatal("Whisper CLI is unavailable: $config{WHISPER_CLI}");
    -x $config{WHISPER_SERVER} && -f $config{WHISPER_SERVER}
        or fatal("Whisper server is unavailable: $config{WHISPER_SERVER}");
    -r $config{WHISPER_MODEL} && -f $config{WHISPER_MODEL}
        or fatal("Whisper model is unavailable: $config{WHISPER_MODEL}");
    $config{WHISPER_RUNTIME_THREADS} =~ /\A(?:auto|[1-9][0-9]*)\z/
        or fatal('WHISPER_RUNTIME_THREADS must be auto or a positive integer');
    $config{WHISPER_PERSISTENT_MEM} =~ /\A[01]\z/
        or fatal('WHISPER_PERSISTENT_MEM must be 0 or 1');
    return \%config;
}

sub runtime_thread_count {
    my ($configured) = @_;
    return $configured if $configured ne 'auto';
    my $count = eval {
        my $value = POSIX::sysconf(POSIX::_SC_NPROCESSORS_ONLN());
        return $value if defined $value && $value > 0;
        return undef;
    };
    return $count if defined $count && $count =~ /\A[1-9][0-9]*\z/;
    return 1;
}

sub whisper_persistent_memory_enabled {
    my ($config) = @_;
    return $config->{WHISPER_PERSISTENT_MEM} eq '1';
}

sub pw_record_binary {
    my $path = $ENV{WHISPER_PW_RECORD_BIN} // '/usr/bin/pw-record';
    assert_safe_absolute_path('pw-record path', $path);
    -x $path && -f $path
        or fatal("pw-record is unavailable: $path");
    return $path;
}

sub set_default_audio_source_muted {
    my ($muted) = @_;
    $muted == 0 || $muted == 1
        or fatal('default audio source mute state must be 0 or 1');

    my $wpctl = '/usr/bin/wpctl';
    -x $wpctl && -f $wpctl
        or fatal("wpctl is unavailable: $wpctl");
    my $status = system {
        $wpctl
    } $wpctl, 'set-mute', '@DEFAULT_AUDIO_SOURCE@', "$muted";
    return if $status == 0;

    my $detail = $status == -1
        ? "exec error: $!"
        : 'exit status ' . ($status >> 8);
    fatal("cannot set default audio source mute state: $detail");
}

sub user_systemctl {
    my (@arguments) = @_;
    my $systemctl = '/usr/bin/systemctl';
    -x $systemctl && -f $systemctl
        or fatal("systemctl is unavailable: $systemctl");
    return system {
        $systemctl
    } $systemctl, '--user', @arguments;
}

sub systemctl_status_detail {
    my ($status) = @_;
    return "exec error: $!" if $status == -1;
    return 'terminated by signal ' . ($status & 127)
        if $status & 127;
    return 'exit status ' . ($status >> 8);
}

sub record_service_is_active {
    return user_systemctl('--quiet', 'is-active', $RECORD_SERVICE) == 0;
}

sub record_service_is_failed {
    return user_systemctl('--quiet', 'is-failed', $RECORD_SERVICE) == 0;
}

sub server_service_is_active {
    return user_systemctl('--quiet', 'is-active', $SERVER_SERVICE) == 0;
}

sub wait_for_record_service_active {
    for (1 .. 50) {
        return 1 if record_service_is_active();
        return 0 if record_service_is_failed();
        sleep 0.1;
    }
    return 0;
}

sub wait_for_record_service_inactive {
    for (1 .. 150) {
        return 1 unless record_service_is_active();
        sleep 0.1;
    }
    return 0;
}

sub timestamp_stem {
    my ($audio_directory) = @_;
    for (1 .. 3) {
        my $stem = strftime('%Y-%m-%d-%H-%M-%S', localtime);
        my $candidate = safe_child_path($audio_directory, "$stem.wav");
        return $stem unless -e $candidate;
        sleep 1.0;
    }
    fatal('could not create a collision-free timestamped recording name');
}

sub assert_state_wav_path {
    my ($paths, $state) = @_;
    my $expected_wav = safe_child_path($paths->{audio}, "$state->{stem}.wav");
    $state->{wav} eq $expected_wav
        or fatal('runtime state recording path is outside the managed audio directory');
    return $expected_wav;
}

sub state_wav_has_audio {
    my ($paths, $state) = @_;
    my $wav = assert_state_wav_path($paths, $state);
    return -f $wav && !-l $wav && -s $wav > 44;
}

sub start_recording {
    my ($runtime, $home) = @_;
    my $paths = resolved_recording_paths($home);
    my $state = read_state($runtime);
    if (record_service_is_active()) {
        $state or fatal('the Whisper recorder is active without managed runtime state');
        assert_state_wav_path($paths, $state);
        set_default_audio_source_muted(0);
        return;
    }
    if ($state) {
        if (state_wav_has_audio($paths, $state)) {
            fatal('a completed Whisper recording is pending transcription; retry stop before starting another recording');
        }
        clear_state($runtime);
    }

    my $stem = timestamp_stem($paths->{audio});
    my $wav = safe_child_path($paths->{audio}, "$stem.wav");
    write_state(
        $runtime,
        {
            stem => $stem,
            wav  => $wav,
        },
    );

    # Keep the microphone muted when idle. Unmute it before requesting the
    # user manager to open the capture stream so Waybar's native
    # {format_source} becomes active when the recorder starts.
    set_default_audio_source_muted(0);
    user_systemctl('reset-failed', $RECORD_SERVICE);
    my $status = user_systemctl('start', $RECORD_SERVICE);
    if ($status == 0 && wait_for_record_service_active()) {
        return;
    }

    my $detail = systemctl_status_detail($status);
    user_systemctl('stop', $RECORD_SERVICE) if record_service_is_active();
    clear_state($runtime);
    set_default_audio_source_muted(1);
    fatal("cannot start $RECORD_SERVICE: $detail");
}

sub record_worker {
    my ($runtime, $home) = @_;
    my $state = read_state($runtime)
        or fatal('the recorder service was started without managed runtime state');
    my $paths = resolved_recording_paths($home);
    my $wav = assert_state_wav_path($paths, $state);
    my $recording_guard = open_recording_guard($runtime, LOCK_EX | LOCK_NB);
    defined $recording_guard
        or fatal('a Whisper recording is already active');
    my $pw_record = pw_record_binary();

    exec {
        $pw_record
    } $pw_record, '--rate=16000', '--channels=1', '--format=s16', $wav
        or fatal("cannot exec pw-record: $!");
}

sub normalize_transcript {
    my ($text) = @_;
    $text = q{} unless defined $text;
    $text =~ s/[\p{Cc}\p{Cf}]+/ /gu;
    $text =~ s/\s+/ /gu;
    $text =~ s/\A\s+//u;
    $text =~ s/\s+\z//u;
    return $text;
}

sub transcript_from_whisper_json {
    my ($data) = @_;
    my @parts;
    if (ref $data->{transcription} eq 'ARRAY') {
        for my $segment (@{ $data->{transcription} }) {
            next unless ref $segment eq 'HASH' && defined $segment->{text};
            push @parts, $segment->{text};
        }
    } elsif (ref $data->{segments} eq 'ARRAY') {
        for my $segment (@{ $data->{segments} }) {
            next unless ref $segment eq 'HASH' && defined $segment->{text};
            push @parts, $segment->{text};
        }
    } elsif (defined $data->{text}) {
        push @parts, $data->{text};
    } elsif (ref $data->{result} eq 'HASH' && defined $data->{result}{text}) {
        push @parts, $data->{result}{text};
    }
    return normalize_transcript(join q{ }, @parts);
}

sub append_todo_entry {
    my ($sleek, $stem, $text) = @_;
    return unless length $text;
    my $lock_path = safe_child_path($sleek->{directory}, '.whisper.txt.lock');
    sysopen my $lock, $lock_path, O_CREAT | O_RDWR, 0600
        or fatal("cannot open Sleek task lock: $!");
    flock($lock, LOCK_EX)
        or fatal("cannot lock Sleek task file: $!");
    open my $fh, '>>:encoding(UTF-8)', $sleek->{task_file}
        or fatal("cannot append to Sleek task file: $!");
    my $date = substr($stem, 0, 10);
    print {$fh} "$date $text +whisper \@voice source:$stem\n"
        or fatal("cannot write Sleek task entry: $!");
    close $fh or fatal("cannot close Sleek task file: $!");
}

sub prune_timestamped_files {
    my ($directory, $extension) = @_;
    opendir my $dh, $directory
        or fatal("cannot read managed directory: $!");
    my @files = grep {
        /\A[0-9]{4}-[0-9]{2}-[0-9]{2}-[0-9]{2}-[0-9]{2}-[0-9]{2}\.\Q$extension\E\z/
            && -f File::Spec->catfile($directory, $_)
            && !-l File::Spec->catfile($directory, $_)
    } readdir $dh;
    closedir $dh or fatal("cannot close managed directory: $!");
    @files = sort { $b cmp $a } @files;
    for my $filename (@files[$MAX_ARTIFACTS .. $#files]) {
        unlink safe_child_path($directory, $filename)
            or fatal("cannot prune managed artifact $filename: $!");
    }
}

sub transcribe_with_whisper_cli {
    my ($config, $state, $output_prefix) = @_;
    my $threads = runtime_thread_count($config->{WHISPER_RUNTIME_THREADS});
    my @command = (
        $config->{WHISPER_CLI},
        '--model', $config->{WHISPER_MODEL},
