sub run_persistent_server {
    my $config = whisper_config();
    whisper_persistent_memory_enabled($config)
        or fatal('WHISPER_PERSISTENT_MEM must be enabled to start whisper-server.service');

    my $threads = runtime_thread_count($config->{WHISPER_RUNTIME_THREADS});
    my @command = (
        $config->{WHISPER_SERVER},
        '--host', '127.0.0.1',
        '--port', '8080',
        '--model', $config->{WHISPER_MODEL},
        '--threads', "$threads",
        '--no-timestamps',
    );
    exec { $command[0] } @command
        or fatal("cannot exec Whisper server: $!");
}

sub main {
    @ARGV <= 1
        or fatal('usage: whisper-record-toggle [start|stop|toggle|record-worker|transcribe|server-enabled|server]');
    my $action = $ARGV[0] // 'toggle';
    $action =~ /\A(?:start|stop|toggle|record-worker|transcribe|server-enabled|server)\z/
        or fatal('usage: whisper-record-toggle [start|stop|toggle|record-worker|transcribe|server-enabled|server]');

    my $runtime = runtime_directory();
    my $home = home_directory();
    if ($action eq 'server-enabled') {
        my $config = whisper_config();
        whisper_persistent_memory_enabled($config)
            or fatal('WHISPER_PERSISTENT_MEM is disabled');
        return;
    }
    if ($action eq 'server') {
        run_persistent_server();
        return;
    }
    if ($action eq 'record-worker') {
        my $lock = open_runtime_lock($runtime, LOCK_EX);
        record_worker($runtime, $home);
        return;
    }
    if ($action eq 'transcribe') {
        my $lock = open_runtime_lock($runtime, LOCK_EX);
        transcribe_pending_recording($runtime, $home);
        return;
    }

    my $transcribe = 0;
    my $lock = open_runtime_lock($runtime, LOCK_EX);
    my $state = read_state($runtime);
    if ($action eq 'toggle') {
        if (record_service_is_active() || $state) {
            $transcribe = defined stop_recording($runtime, $home);
        } else {
            start_recording($runtime, $home);
        }
    } elsif ($action eq 'start') {
        start_recording($runtime, $home);
    } else {
        $transcribe = defined stop_recording($runtime, $home);
    }
    undef $lock;
    start_transcribe_service() if $transcribe;
}

main();

