package ExternalSoftware::Servicing::CLI;

use strict;
use warnings;

use Moo;
use MooX::StrictConstructor;

use Digest::SHA qw(sha256_hex);
use ExternalSoftware::Servicing::Deb;
use ExternalSoftware::Servicing::Event;
use ExternalSoftware::Servicing::HTTP;
use ExternalSoftware::Servicing::Ledger;
use ExternalSoftware::Servicing::Notifier;
use ExternalSoftware::Servicing::Obsidian;
use ExternalSoftware::Servicing::Repository;
use ExternalSoftware::Servicing::State;
use ExternalSoftware::Servicing::Tuta;

sub _log {
    my ($self, $level, $message) = @_;
    print STDERR "[managed-external-software-update] $level: $message\n";
    system('/usr/bin/logger', '-t', 'managed-external-software-update', '--', "$level: $message") if -x '/usr/bin/logger';
}

sub _deb_update {
    my ($self, $http, $deb, $event, $work, $app) = @_;
    my $path = "$work/$app->{name}.deb";
    eval {
        $http->download(
            label => $app->{label}, url => $app->{url}, destination => $path,
            minimum => 1_048_576, maximum => $app->{maximum}, allowed_hosts => $app->{hosts},
            content_policy => 'artifact',
        );
        my $metadata = $deb->validate(
            label => $app->{label}, path => $path, packages => $app->{packages},
            executable => $app->{executable}, desktop => $app->{desktop}, library => $app->{library},
        );
        my $installed = $deb->installed_version($metadata->{package});
        if (defined $installed) {
            system('/usr/bin/dpkg', '--compare-versions', $metadata->{version}, 'lt', $installed) == 0
                and die "downgrade\n";
            return 2 if system('/usr/bin/dpkg', '--compare-versions', $metadata->{version}, 'eq', $installed) == 0;
        }
        $event->emit('updating', $app->{name}, $installed // 'missing', $metadata->{version});
        $deb->repository()->retain($path, $metadata);
        $deb->install($path);
        my $verified = $deb->installed_version($metadata->{package});
        defined $verified && $verified eq $metadata->{version}
            or die "postinstall verification failed\n";
        -x $app->{executable} && -r $app->{desktop}
            or die "postinstall payload validation failed\n";
        $event->emit('updated', $app->{name}, $installed // 'missing', $metadata->{version});
        return 0;
    };
    my $error = $@;
    return ($error =~ /downgrade/i ? 1 : 1, $error =~ /downgrade/i ? 'downgrade' : 'validation');
}

sub run_updater {
    my ($self, @argv) = @_;
    @argv <= 1 && (!@argv || $argv[0] eq '--repair-only') or die "usage: managed-external-software-update [--repair-only]\n";
    $> == 0 or die "this updater must run as root\n";
    open my $arch_fh, '-|', '/usr/bin/dpkg', '--print-architecture'
        or die "dpkg is unavailable\n";
    my $architecture = <$arch_fh> // q{};
    close $arch_fh or die "dpkg architecture query failed\n";
    chomp $architecture;
    $architecture eq 'amd64' or die "managed external software updates are supported only on amd64\n";
    my $state = ExternalSoftware::Servicing::State->new();
    $state->prepare();
    my $lock = $state->lock();
    if (!defined $lock) {
        $self->_log('info', 'another managed external software update is already running');
        return 0;
    }
    my $work = $state->work_dir();
    my $event = ExternalSoftware::Servicing::Event->new(directory => $state->event_dir());
    my $http = ExternalSoftware::Servicing::HTTP->new();
    my $repository = ExternalSoftware::Servicing::Repository->new(directory => $state->deb_dir());
    my $deb = ExternalSoftware::Servicing::Deb->new(repository => $repository);
    my @deb_specs = (
        { name => 'bitwarden', label => 'Bitwarden Desktop', url => 'https://bitwarden.com/download/?app=desktop&platform=linux&variant=deb', maximum => 314_572_800, hosts => [qw(bitwarden.com github.com objects.githubusercontent.com release-assets.githubusercontent.com)], packages => ['bitwarden'], executable => '/opt/Bitwarden/bitwarden', desktop => '/usr/share/applications/bitwarden.desktop', library => '/opt/Bitwarden/libffmpeg.so' },
        { name => 'obsidian', label => 'Obsidian', packages => ['obsidian'], executable => '/opt/Obsidian/obsidian', desktop => '/usr/share/applications/obsidian.desktop', library => '/opt/Obsidian/libffmpeg.so' },
        { name => 'zoom', label => 'Zoom Workplace', url => 'https://zoom.us/client/latest/zoom_amd64.deb', maximum => 536_870_912, hosts => [qw(zoom.us cdn.zoom.us)], packages => ['zoom'], executable => '/usr/bin/zoom', desktop => '/usr/share/applications/Zoom.desktop', library => q{} },
        { name => 'filen', label => 'Filen Desktop', url => 'https://cdn.filen.io/@filen/desktop/release/latest/Filen_linux_amd64.deb', maximum => 536_870_912, hosts => [qw(cdn.filen.io filen.io)], packages => [qw(filen filen-desktop)], executable => '/opt/Filen/Filen', desktop => '/usr/share/applications/Filen.desktop', library => '/opt/Filen/libffmpeg.so' },
        { name => 'discord', label => 'Discord', url => 'https://discord.com/api/download?platform=linux&format=deb', maximum => 536_870_912, hosts => [qw(discord.com discordapp.com discordapp.net stable.dl2.discordapp.net)], packages => ['discord'], executable => '/usr/bin/discord', desktop => '/usr/share/applications/discord.desktop', library => q{} },
    );
    my ($updated, $failed) = (0, 0);
    eval {
        my $repair_failed = 0;
        for my $spec (@deb_specs) {
            $repair_failed = 1 if !$repository->repair($deb, $spec);
        }
        if (@argv && $argv[0] eq '--repair-only') {
            $self->_log(
                $repair_failed ? 'warning' : 'info',
                $repair_failed
                    ? 'one or more managed Debian packages could not be repaired offline'
                    : 'managed Debian package offline repair completed',
            );
            $state->cleanup_work_dir($work);
            return $repair_failed ? 1 : 0;
        }
        $event->emit('checking', 'all', '-', '-');
        for my $app (grep { $_->{name} ne 'obsidian' } @deb_specs) {
            my ($result, $reason) = $self->_deb_update($http, $deb, $event, $work, $app);
            $updated++ if $result == 0;
            if ($result == 1) { $failed++; $event->emit('failed', $app->{name}, $reason, '-'); }
        }
        my ($obsidian_result, $obsidian_reason) =
            ExternalSoftware::Servicing::Obsidian->new(http => $http, deb => $deb, event => $event)->update($work);
        if ($obsidian_result == 0) {
            $updated++;
        } elsif ($obsidian_result == 1) {
            $failed++;
            $event->emit('failed', 'obsidian', $obsidian_reason, '-');
        }
        my ($tuta_result, $tuta_reason) = ExternalSoftware::Servicing::Tuta->new(http => $http, event => $event, state => $state)->update($work);
        if ($tuta_result == 0) {
            $updated++;
        } elsif ($tuta_result == 1) {
            $failed++;
            $event->emit('failed', 'tuta', $tuta_reason, '-');
        }
        my ($ledger_result, $ledger_reason) = ExternalSoftware::Servicing::Ledger->new(http => $http, event => $event, state => $state)->update($work);
        if ($ledger_result == 0) {
            $updated++;
        } elsif ($ledger_result == 1) {
            $failed++;
            $event->emit('failed', 'ledger', $ledger_reason, '-');
        }
        $event->emit($updated || $failed ? 'complete' : 'no-updates', 'all', $updated || 0, $failed || 0);
        1;
    };
    my $error = $@;
    $state->cleanup_work_dir($work);
    die $error if $error;
    return $failed ? 1 : 0;
}

sub run_notifier {
    my ($self, @argv) = @_;
    @argv == 0 or die "usage: managed-external-software-notify\n";
    return ExternalSoftware::Servicing::Notifier->new()->run();
}

1;



