use DigitalAssets::Runtime;

option help => (
    is      => 'ro',
    isa     => Bool,
    default => sub { 0 },
    doc     => 'print usage',
);

sub run {
    my ($class, @argv) = @_;
    if (@argv == 1 && $argv[0] eq '--help') {
        print STDERR "usage: labwc-digital-assets-action [--run] <action> <file-or-list>\n";
        return 0;
    }
    return DigitalAssets::Runtime->new()->run(@argv);
}

