    57	        debug   => LOG_DEBUG,
    58	        info    => LOG_INFO,
    59	        warning => LOG_WARNING,
    60	        error   => LOG_ERR,
    61	    );
    62	    my $line = _normalize_message($message);
    63	    return if !eval {
    64	        openlog('zram-writeback', 'pid,nowait', LOG_DAEMON);
    65	        syslog($priority{$level} // LOG_ERR, '%s', $line);
