  [ -f "$bookmark_json" ] && [ ! -L "$bookmark_json" ] && [ -s "$bookmark_json" ] ||
    fatal "pdfcpu did not produce a valid bookmarks.json working file"
  chmod 0600 "$bookmark_json"

  printf '%s\n' \
    'Edit bookmarks.json in Nano, save, then exit Nano to write a new PDF with the edited bookmark tree.'
  nano "$bookmark_json"
  [ -f "$bookmark_json" ] && [ ! -L "$bookmark_json" ] && [ -s "$bookmark_json" ] ||
    fatal "the edited bookmarks.json working file is invalid"

  prepare_output_file pdf-bookmarks-edited pdf "$input_path"
  # The source PDF already has an outline because it was exported above.
  # --replace is therefore required to replace that existing outline.
  run_timed pdfcpu bookmarks import \
    "$input_path" \
    "$bookmark_json" \
    "$OUTPUT_PATH" \
    --replace
  run_timed pdfcpu validate "$OUTPUT_PATH"
  report_file_output "$OUTPUT_PATH" 'PDF with edited bookmarks'
