package DigitalAssets::Artifacts;

use strict;
use warnings;

use File::Path qw(make_path);
use File::Spec;
use Moo;
use MooX::StrictConstructor;
use MooX::TypeTiny;
use Types::Standard qw(Str);

has home => (
    is      => 'ro',
    isa     => Str,
    lazy    => 1,
    builder => sub { $ENV{HOME} // q{} },
);

sub output_root {
    my ($self) = @_;
    my $home = $self->home();
    $home =~ m{\A/} && -d $home && !-l $home && (lstat $home)[4] == $<
        or die "labwc-digital-assets-action: HOME is unsafe\n";
    my $root = File::Spec->catdir($home, 'Documents', 'Digital-Assets');
    make_path($root, { mode => 0700 }) if !-e $root;
    -d $root && !-l $root && (lstat $root)[4] == $<
        or die "labwc-digital-assets-action: Digital Assets output root is unsafe\n";
    chmod 0700, $root or die "labwc-digital-assets-action: cannot secure output root: $!\n";
    return $root;
}

